command:
// GM: rewrites the descriptions of the ten core Role items (world Items and characters' copies):
// a few lines of flavor, then what the Role Ability does, with links to the Core rulebook journal.
// Only descriptions that are still the system's stock text are replaced; edited ones are left alone.
if ( !game.user.isGM ) return ui.notifications.warn("Only a GM can update Role descriptions.");

// {{role}} / {{ability}} become links to the Role's page and its Role Ability page in the Core journals.
const ROLES = {
  Rockerboy: { ability: "Charismatic Impact", page: 144, html: `
<p><em>The street poets and loudest consciences of the Time of the Red. A Rockerboy doesn't need a Corp contract or a stadium, just a message, a crowd, and the nerve to aim one at the people who run this world. Some play guitar; others preach, paint, or dance. All of them make the powerful nervous.</em></p>
<p><strong>Role Ability: Charismatic Impact.</strong> Sway Fans by sheer force of personality. It needn't be music: poetry, art, dance, speeches, or plain presence all work. A Rockerboy can be a rocker, or a cult leader.</p>
<ul>
<li><strong>Making Fans:</strong> outside combat, roll Charismatic Impact + 1d10 vs DV8 (one person), DV10 (small group of up to 6), or DV12 (huge group). Doesn't work on anyone who actively dislikes you. The GM decides who is already a Fan.</li>
<li><strong>Asking a favor:</strong> works on Fans only. If the favor is beyond your Rank, it fails automatically; otherwise roll against the same DVs by group size. On a failure, those Fans won't do that favor for a week.</li>
<li><strong>What Rank buys:</strong> venues grow from small local clubs (Rank 1–2) to huge stadiums and international video (10). A single Fan goes from buying you a drink to risking, and finally giving, their life for you; a huge crowd goes from "you don't have one yet" to a worldwide, cult-like private army.</li>
</ul>
<p>Core: {{role}} · {{ability}}</p>` },

  Solo: { ability: "Combat Awareness", page: 146, html: `
<p><em>Bodyguards, assassins, and soldiers-for-hire: the elite fighting machines of the Time of the Red. Most Solos learned their trade in the 4th Corporate War and paid for it in meat, trading lost flesh for chrome and frayed nerves for combat drugs. The best go ronin and sell their talents to whoever can afford them. It costs them dearly, and they pay it, because they're the best.</em></p>
<p><strong>Role Ability: Combat Awareness.</strong> Split points equal to your Rank among the abilities below. Reassign them when combat begins (before Initiative), any time outside combat, or with an Action in combat; if you don't, the last split stays.</p>
<ul>
<li><strong>Damage Deflection:</strong> every 2 points reduce the first damage you take each Round by 1 (up to 5 for 10 points).</li>
<li><strong>Fumble Recovery</strong> (4 points): ignore critical failures (1s) on your attacks; the die still counts as 1.</li>
<li><strong>Initiative Reaction:</strong> +1 to Initiative per point.</li>
<li><strong>Precision Attack:</strong> +1 to all Attacks per 3 points (up to +3 for 9 points).</li>
<li><strong>Spot Weakness:</strong> +1 damage (before armor) to your first successful Attack each Round, per point.</li>
<li><strong>Threat Detection:</strong> +1 to Perception Checks per point.</li>
</ul>
<p>Core: {{role}} · {{ability}}</p>` },

  Netrunner: { ability: "Interface", page: 147, html: `
<p><em>Brain-burning hackers of the post-NET world. The Old NET died in the 4th Corporate War, so today's Netrunners can't roam the planet from a couch: they jack in on site, in a bodysuit and goggles, with a crew guarding their meat. Inside, they're ghosts, slipping through Architectures to steal secrets while dodging Black ICE that can stop a heart.</em></p>
<p><strong>Role Ability: Interface.</strong> Lets you Netrun: link a cyberdeck to computers, electronics, and their programs and take control of them.</p>
<ul>
<li><strong>NET Actions per Turn:</strong> 2 at Rank 1–3, 3 at 4–6, 4 at 7–9, 5 at 10.</li>
<li><strong>Interface Abilities:</strong> Backdoor (break through Passwords and other obstacles), Cloak (hide your traces before you leave), Control (operate what's attached to the Architecture), Eye-Dee (identify found data and its value), Pathfinder (map the Architecture), Scanner (locate systems in the area), Slide (shake off one pursuing Black ICE), Virus (leave a custom virus at the Architecture's core), Zap (a basic attack on Programs and other Netrunners).</li>
<li>Netrunning in full: Core p.198.</li>
</ul>
<p>Core: {{role}} · {{ability}}</p>` },

  Tech: { ability: "Maker", page: 147, html: `
<p><em>Renegade mechanics and garage geniuses: the people who keep a broken world running. With the supply chain shattered by the War, every working blender, Agent, and Metrocar is worth saving, and a Tech can fix, upgrade, or rebuild nearly all of it. The real money is in black-market work (illegal weapons, stolen cyberware, spy gear for Corporate black ops), which is also why there are turrets by the front door.</em></p>
<p><strong>Role Ability: Maker.</strong> Repair, improve, build, and invent. Each Maker Rank also gives 1 Rank in two different Specialties.</p>
<ul>
<li><strong>Field Expertise:</strong> add its Rank to Basic Tech, Cybertech, Electronics/Security Tech, Weaponstech, and Land/Sea/Air Vehicle Tech Checks made for non-Maker purposes. Jury-rig a broken item to perfect condition as an Action (same DV as a repair); it holds 10 minutes per Rank, then reverts and needs a full repair before it can be rigged again.</li>
<li><strong>Upgrade Expertise:</strong> one upgrade per item, e.g. cut a cyberware's Humanity Loss by 1d6, add a slot, make a one-handed weapon concealable, raise a weapon to Excellent Quality, add 1 SP, give a vehicle a Moto Rank 1 upgrade, or install your own invention. Materials cost the item's price category.</li>
<li><strong>Fabrication Expertise:</strong> build existing items or your inventions from materials one price category cheaper (Super Luxury: half its price).</li>
<li><strong>Invention Expertise:</strong> design a new item or upgrade. Describe how it works; the GM writes its rules and sets its price category (Expensive at least).</li>
<li><strong>The roll:</strong> TECH + the Skill that repairs the item + Specialty Rank + 1d10. DV and time by price category: Cheap/Everyday DV9, 1 hour · Costly DV13, 6 hours · Premium DV17, 1 day · Expensive DV21, 1 week · Very Expensive DV24, 2 weeks · Luxury DV29, 1 month · Super Luxury DV29, 1 month per 10,000eb. A failure means starting over; the materials aren't lost.</li>
</ul>
<p>Core: {{role}} · {{ability}}</p>` },

  Medtech: { ability: "Medicine", page: 149, html: `
<p><em>Street doctors, ripperdocs, and Trauma Team medics, patching up meat and metal alike. A lucky few went to a real med school; more learned in wartime field hospitals or at an old ripper's elbow. When half your patients are more machine than human, you're as much mechanic as doctor, and whatever brought you to The Street, the work never stops coming.</em></p>
<p><strong>Role Ability: Medicine.</strong> Keep alive the people who should be dead. Each Rank puts 1 point into one of three Specialties.</p>
<ul>
<li><strong>Surgery:</strong> +2 Surgery Skill per point (max 10). Treats the worst Critical Injuries and installs cyberware. Only Medtechs have this Skill.</li>
<li><strong>Medical Tech (Pharmaceuticals)</strong> (max 5 points): +1 Medical Tech per point, and one drug per point: Antibiotic, Rapidetox, Speedheal, Stim, or Surge. Making them takes a DV13 Medical Tech Check (materials lost on a failure): 200eb of materials and 1 hour give as many doses as your Medical Tech Skill. Only a Medtech can administer them properly.</li>
<li><strong>Medical Tech (Cryosystem Operation)</strong> (max 5 points): +1 Medical Tech per point. 1: a Cryopump. 2: Registered Cryotank Technician, with 24/7 access to one Cryotank at corporate or government facilities. 3: your own Cryotank. 4: two more Cryotanks; the pump holds 2 charges and 2 people. 5: three more Cryotanks; 3 charges and 3 people.</li>
<li><strong>Medtech-only care:</strong> cyberware installation and removal, Bodysculpting, and Therapy (Core p.226).</li>
</ul>
<p>Core: {{role}} · {{ability}}</p>` },

  Media: { ability: "Credibility", page: 151, html: `
<p><em>Reporters, streamers, and screamsheet legends who dig up what the powerful want buried. The War tore the mask off the Corporations, and the Medias made sure everyone saw it. With no Mediacorp behind them now, they live on their fans, their sources, and their reputation, which also makes them harder to quietly disappear. Some threads are dangerous to pull. A Media pulls them anyway.</em></p>
<p><strong>Role Ability: Credibility.</strong> How far your stories reach, how many believe them, and who will talk to you.</p>
<ul>
<li><strong>Rumors:</strong> at least twice a week the GM secretly rolls Credibility + 1d10 and tells you the best rumor it beats: Vague DV7, Typical DV9, Substantial DV11, Detailed DV13. Hunting one actively is STAT + Skill (Library Search, Conversation, Interrogation…) + 1d10 vs DV13 / 15 / 17 / 21.</li>
<li><strong>Access/Sources:</strong> from local honchos and gang lords (Rank 1–2) up to world leaders and Megacorp heads (10).</li>
<li><strong>Audience:</strong> your neighborhood (1–2), the local screamsheets and Data Pool (3–4), Citywide (5–6), Statewide (7–8), national (9), worldwide (10).</li>
<li><strong>Believability:</strong> roll 1d10 when you publish: 2 in 10 the audience buys it at Rank 1–2, rising by 1 per step to 7 in 10 at Rank 10. +1 for a piece of clear, verifiable evidence, and +2 more for over four pieces. No LUCK on this roll.</li>
<li><strong>Impact:</strong> from scaring small-time crooks into behaving to toppling Megacorps and governments; the GM decides. One story per topic, unless you have something new.</li>
</ul>
<p>Core: {{role}} · {{ability}}</p>` },

  Exec: { ability: "Teamwork", page: 153, html: `
<p><em>Corporate climbers and business raiders, fighting to put the Megacorps back on top and themselves at the head of them. Before the War it was an MBA's fast track; now it's a knife fight in a good suit, with rivals above and below who mean "kill for your job" literally. Every Exec keeps specialists on the payroll for pet projects and the occasional extraction. Ideals tarnish. The report is still due in an hour.</em></p>
<p><strong>Role Ability: Teamwork.</strong> The Corporation provides perks and a team of employees who help you, legally or not, morale permitting.</p>
<ul>
<li><strong>Rank 1:</strong> a full Businesswear suit (reselling it raises suspicion).</li>
<li><strong>Corporate Housing:</strong> a rent-free Corporate Conapt at Rank 2 (your Lifestyle is still yours to pay), a Beaverville House at 7, a Beaverville McMansion or Luxury Penthouse at 10.</li>
<li><strong>Health insurance:</strong> Trauma Team Silver at Rank 6, Trauma Team Executive at 8, paid by the Corp.</li>
<li><strong>Team Members</strong> at Ranks 3, 5, and 9 (max 3): Bodyguard, Covert Operative, Driver, Netrunner, or Technician, each with a cover job. GM-run, they never improve their Skills and wear only Light Armorjack. A lost one is replaced next session with Loyalty 1, plus 200eb in "hiring fees".</li>
<li><strong>Loyalty:</strong> starts at 1d6+1. Each order needs a 1d6 roll under Loyalty, or it's refused, botched, or worse. Praise, bonuses, a cut of the pay, paid time off, and risking yourself for them raise it; chewing them out, ignoring them, and leaving them under fire lower it. At 0 or below, they betray you.</li>
<li><strong>Fired?</strong> You'll have a new gig within a week, and the Role Ability carries over.</li>
</ul>
<p>Core: {{role}} · {{ability}}</p>` },

  Lawman: { ability: "Backup", page: 158, html: `
<p><em>Beat cops, corporate security, County Mounties, and Psycho Squad heavies: whatever the badge, Lawmen are the ones holding back the chaos. The Street is meaner than ever, flooded with milspec chrome and out-of-work Corp mercs, and the cops are usually outgunned. They put on the armor and walk the beat anyway, because someone has to.</em></p>
<p><strong>Role Ability: Backup.</strong> Call fellow officers when things go wrong. The GM plays them.</p>
<ul>
<li><strong>Calling it in:</strong> as an Action, roll 1d10 equal to or under your Backup Rank. If someone answers, roll 1d6 for the Rounds until they arrive; on a 6, the next tier up comes instead (two groups at Rank 10). If nobody answers, try again next Turn. Abuse it and your Boss fines you or throws you off the force.</li>
<li><strong>Who comes</strong> (any tier up to your Rank): 1–2 Corporate Security, four rent-a-cops on foot · 3–4 Local Beat Cops, four in two Compact Groundcars · 5–7 Sheriff's Department, two in a High Performance Groundcar with assault rifles · 8 a Recovery Zone Marshal on a Superbike · 9 C-SWAT, two Psycho Squad heavies in Metalgear from an AV-4 · 10 National Law Enforcement, Interpol, FBI, or Netwatch: two serious hitters in an AV-4 who stay to investigate, and the same pair answers for the rest of the case.</li>
<li><strong>Backup in a fight:</strong> one Combat Number for attack and defense (+1d10); they can't dodge bullets.</li>
<li>Higher Ranks tend to bring promotions, and job offers from the agencies you can call.</li>
</ul>
<p>Core: {{role}} · {{ability}}</p>` },

  Fixer: { ability: "Operator", page: 159, html: `
<p><em>Dealmakers, smugglers, and information brokers at the center of every web on The Street. Not cut out for a Corp job and not tough enough to be a Solo, a Fixer learned early what people want and how to get it for them, for a price. They run guns over borders, broker Solos, buy into the hottest nightclubs, and negotiate between warring factions. One part Robin Hood, two parts Al Capone; once, they'd have been called crime lords.</em></p>
<p><strong>Role Ability: Operator.</strong> Contacts, black-market sourcing, deal-making, and fitting in anywhere on The Street.</p>
<ul>
<li><strong>Contacts &amp; Clients:</strong> from local honchos and gang lords (Rank 1–2) up to world leaders and Megacorp heads (10). You still pay for what they provide.</li>
<li><strong>Reach</strong> (what you can always source): Cheap and Everyday (1–2), up to Expensive (3–4), up to Very Expensive (7–8), Luxury (9), Super Luxury (10). From Rank 5, organize a Night Market with other Fixers once a month and find anything there; from 9, add a Midnight Market for the underworld's leaders.</li>
<li><strong>Haggle:</strong> COOL + Trading + Operator + 1d10 vs theirs; win and make one deal of your Rank or lower per transaction: 10% off or on the price (1–2), buy 5 get 1 free (3–4), +20% Job pay (5–6), half now and half next month on Luxury goods (7–8), 20% off or on (9), double pay for a Dangerous Job (10).</li>
<li><strong>Grease:</strong> you know your neighborhood and its gangs (1–2), then more local cultures and their languages at Skill Level 4: 1 more (3–4), 3 in total (5–6), 6 in total (7–8). At 9 you also blend into Corporate and government circles; at 10, almost any group, secret societies and cults included.</li>
</ul>
<p>Core: {{role}} · {{ability}}</p>` },

  Nomad: { ability: "Moto", page: 161, html: `
<p><em>Road warriors, smugglers, convoy crews, and air-pirates: the Families who keep the world connected. Driven off their land by the Corps before the War, the Nomad Packs became towns on wheels; in the Time of the Red, they're the ones who can reliably move people and cargo down the savage highways between safe zones. Every kid can shoot, every vehicle bristles with stolen weapons, and Family comes first.</em></p>
<p><strong>Role Ability: Moto.</strong> Nomads have better cars, and know exactly how to drive them.</p>
<ul>
<li><strong>Vehicle Familiarity:</strong> add your Moto Rank to Drive Land Vehicle, Pilot Air Vehicle, Pilot Sea Vehicle, and Air/Land/Sea Vehicle Tech Checks.</li>
<li><strong>Family Motorpool:</strong> each time your Rank rises, add a stock vehicle of your Rank or lower to the Family Vehicles you may use, or give one of them an upgrade of your Rank or lower.</li>
<li><strong>Vehicles by Rank:</strong> 1–4 Compact Groundcar, Gyrocopter, Jetski, Roadbike · 5–6 Helicopter, High Performance Groundcar, Speedboat · 7–8 AV-4, Cabin Cruiser, Superbike · 9–10 Aerozep, AV-9, Super Groundcar, Yacht.</li>
<li><strong>Using them:</strong> one Family Vehicle out at a time; call the Family to swap it (next morning, if they're nearby). A destroyed one is rebuilt in a week for 500eb; everyday repairs are yours.</li>
<li><strong>Rank 10:</strong> a leadership position in the Family; all your vehicles can be out at once; further vehicles cost market price and upgrades 1,000eb each.</li>
</ul>
<p>Core: {{role}} · {{ability}}</p>` }
};

const pageLink = (journal, page, label) => {
  const p = game.journal.getName(journal)?.pages.getName(page);
  return p ? `@UUID[${p.uuid}]{${label}}` : label;
};
const describe = (name, { ability, page, html }) => html.trim()
  .replace("{{role}}", pageLink("Soul and the New Machine", name, name))
  .replace("{{ability}}", `${pageLink("Getting it Done", `${name}: ${ability}`, ability)}, p.${page}`);
const norm = s => String(s ?? "").replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/\s+/g, " ").trim();

// The system's stock text per Role: only items still showing it are replaced.
const stock = {};
for ( const doc of await game.packs.get("cyberpunk-red-core.core_roles")?.getDocuments() ?? [] ) {
  stock[doc.name] = norm(doc.system.description?.value);
}
const todo = [];
const skipped = [];
const check = (item, where) => {
  const role = ROLES[item.name];
  if ( (item.type !== "role") || !role ) return;
  const now = norm(item.system.description?.value);
  if ( now === stock[item.name] ) todo.push({ item, html: describe(item.name, role) });
  else if ( now !== norm(describe(item.name, role)) ) skipped.push(`${item.name} (${where})`);
};
for ( const item of game.items ) check(item, "Items");
for ( const actor of game.actors ) for ( const item of actor.items ) check(item, actor.name);

if ( !todo.length ) {
  return ui.notifications.info(skipped.length ? `No stock Role descriptions left; ${skipped.length} edited ones kept.`
    : "Role descriptions are already up to date.");
}
const worldCount = todo.filter(t => !t.item.parent).length;
const kept = skipped.length ? `<p>Edited descriptions are kept: ${skipped.join(", ")}.</p>` : "";
const ok = await Dialog.confirm({
  title: "Update Role descriptions",
  content: `<p>Replace the stock description of ${worldCount} Role item(s) in Items and ${todo.length - worldCount} on characters?</p>${kept}`
});
if ( !ok ) return;
for ( const { item, html } of todo ) await item.update({ "system.description.value": html });
ui.notifications.info(`Updated ${todo.length} Role description(s).`);
